INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT156-S2-Q3$batch08$, 156, 2, 3, $batch08$Paradox$batch08$, $batch08$A recent study has found that, surprisingly, the risk of serious injuries to workers is higher in industries that are monitored by government safety inspectors than in industries that are not so monitored.$batch08$, $batch08$Which one of the following, if true, most helps to explain the surprising finding described above?$batch08$, $batch08$C$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=156 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q3$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$Government safety inspectors not only monitor but also train employees of the inspected firms to follow safe practices.$batch08$, $batch08$Deepens Paradox$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$Government safety inspectors do not have the authority to enforce safety regulations.$batch08$, $batch08$Weaker Impact$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$Only those industries with an inherently high risk of on-the-job injury are monitored by government safety inspectors.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$Workers behave especially cautiously when they believe their performance is being monitored by government safety inspectors.$batch08$, $batch08$Deepens Paradox$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$Some of the industries that are monitored by government safety inspectors have much lower rates of injuries than do other industries that are also so monitored.$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT156-S2-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Given that$batch08$, $batch08$Some industries are monitored by government safety inspectors.$batch08$), (1, $batch08$How can it be that$batch08$, $batch08$Workers in monitored industries face a *higher* risk of serious injury than workers in unmonitored ones?$batch08$), (2, $batch08$Evaluate$batch08$, $batch08$Don't assume the inspectors cause injuries. Ask which industries get inspectors in the first place. If inspectors are sent to the dangerous ones, the monitored group starts out riskier, and the comparison isn't fair.$batch08$), (3, $batch08$Goal$batch08$, $batch08$A reason the monitored industries were riskier to begin with.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT156-S2-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$Inspectors who also train workers in safe practices should make injuries rarer, not more common.$batch08$), ($batch08$B$batch08$, $batch08$No enforcement power might explain why inspections don't *help*. It doesn't explain why monitored industries are *worse*.$batch08$), ($batch08$C$batch08$, $batch08$Only inherently high-risk industries get inspectors. The monitoring follows the danger; it doesn't cause it.$batch08$), ($batch08$D$batch08$, $batch08$More careful workers should mean fewer injuries.$batch08$), ($batch08$E$batch08$, $batch08$Differences among monitored industries don't explain the gap between monitored and unmonitored ones.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT156-S2-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
